import React, { useState } from 'react';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from '../firebase-config'; 

const LogIn = ({ onLogin, isOnline, apiBaseUrl }) => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');

    const manejarSubmit = async (e) => {
        e.preventDefault();
        if (!isOnline) return; 

        try {
            // 1. Firebase
            const userCredential = await signInWithEmailAndPassword(auth, email, password);
            const user = userCredential.user;

            // 2. Tu servidor
            const response = await fetch(`${apiBaseUrl}/usuarios/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ email: user.email }),
            });

            if (response.ok) {
                const datosServidor = await response.json();
                onLogin(datosServidor); 
            }
        } catch (err) {
            setError("Error al entrar: revisa tus datos");
        }
    };

    return (
        <div className="card shadow-sm border-0 mt-3"> 
            <div className="card-header bg-primary text-white text-center">
                <h5 className="mb-0">Identificación</h5>
            </div>
            <div className="card-body">
                <form onSubmit={manejarSubmit}>
                    {error && <div className="alert alert-danger p-2 small">{error}</div>}
                    
                    <div className="mb-3">
                        <label className="form-label small fw-bold">Email</label>
                        <input 
                            type="email" 
                            className="form-control form-control-sm" 
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label small fw-bold">Contraseña</label>
                        <input 
                            type="password" 
                            className="form-control form-control-sm" 
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                        />
                    </div>
                    <button type="submit" className="btn btn-primary w-100 shadow-sm" disabled={!isOnline}>
                        {isOnline ? "Entrar a la tienda" : "Sin conexión"}
                    </button>
                </form>
            </div>
        </div>
    );
}; // <-- ESTA LLAVE ES IMPORTANTE

export default LogIn;
